import {calculateCraft,parseNumber} from './calc.js';
import {mountRefinery,mountDurability,REFINERY_ITEMS} from './refinery.js';

const KEY='rose-forge-v1';
const $=(s,r=document)=>r.querySelector(s);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(value,digits=2)=>Number.isFinite(value)?new Intl.NumberFormat('pl-PL',{maximumFractionDigits:digits}).format(value):'—';
const money=value=>Number.isFinite(value)?`${num(value)} z`:'Brak wyceny';
const int=value=>Number.isFinite(value)?new Intl.NumberFormat('pl-PL',{maximumFractionDigits:0}).format(value):'—';
const compact=value=>Number.isFinite(value)?new Intl.NumberFormat('pl-PL',{notation:'compact',maximumFractionDigits:1}).format(value)+' z':'Dodaj ceny';
const trialWord=n=>n===1?'próbę':n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?'próby':'prób';
const inputValue=value=>value===null||value===undefined?'':esc(String(value));
const paths={
 book:'M4 4h6c2 0 2 1 2 2v15c0-2-2-3-4-3H4zM20 4h-6c-2 0-2 1-2 2v15c0-2 2-3 4-3h4z',
 hammer:'m13 3 8 5-3 5-8-5zM12 9 4 21l-3-2L9 7',
 shield:'M12 3 3 7v6c0 5 9 9 9 9s9-4 9-9V7zM8 12l3 3 5-6',
 bag:'M5 7h14l2 15H3zM8 7V5a4 4 0 0 1 8 0v2',
 cart:'M2 3h3l3 13h11l3-9H6M10 21h.01M18 21h.01',
 gem:'m5 3 14 0 4 7-11 13L1 10zM1 10h22M9 3l-3 7 6 13 6-13-3-7',
 search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',
 arrow:'M4 12h16m-6-6 6 6-6 6',
 star:'m12 2 3 7 8 1-6 5 2 8-7-4-7 4 2-8-6-5 8-1z',
 coins:'M20 5c0 2-4 4-8 4S4 7 4 5s4-4 8-4 8 2 8 4zM4 5v5c0 2 4 4 8 4s8-2 8-4V5M4 10v5c0 2 4 4 8 4s8-2 8-4v-5',
 spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',
 sword:'m18 2 4 4-13 13-4-4zM3 11l10 10M7 17l-5 5',
 flask:'M9 2h6M10 2v7L3 20q-1 2 2 2h14q3 0 2-2L14 9V2M6 15h12',
 gear:'M9 2h6l1 4 4 1 3 5-3 5-4 1-1 4H9l-1-4-4-1-3-5 3-5 4-1zM16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
 info:'M12 11v7m0-12v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
 close:'m6 6 12 12M6 18 18 6',
 check:'m5 12 4 4L20 5',
 download:'M12 2v14m-6-6 6 6 6-6M3 16v6h18v-6',
 upload:'M12 16V2m-6 6 6-6 6 6M3 16v6h18v-6',
 trash:'M3 6h18M9 6V2h6v4M5 6l1 16h12l1-16M10 10v8m4-8v8',
 plus:'M12 3v18M3 12h18',
 link:'M9 15l6-6M8 17l-2 2a4 4 0 0 1-6-6l6-6a4 4 0 0 1 6 0m0 0 2-2a4 4 0 0 1 6 6l-6 6a4 4 0 0 1-6 0',
 cloud:'M6 18a5 5 0 0 1-1-10 7 7 0 0 1 13-1 5 5 0 1 1 0 11H6',
 chevron:'m9 5 7 7-7 7',
};
const icon=(name,extra='')=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" ${extra}><path d="${paths[name]||paths.gem}"/></svg>`;

let state={prices:{},inventory:{},favorites:[],cart:[],choices:{},craftFees:{},recipeRuns:{},patConfirmed:{},recipeEdits:{},refine:{},dura:{}};
let storageAvailable=true;
try {const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&typeof saved==='object') for(const key of Object.keys(state))if(saved[key]&&typeof saved[key]===typeof state[key])state[key]=saved[key];}catch{storageAvailable=false;}
if(!Array.isArray(state.cart))state.cart=[];
if(!Array.isArray(state.favorites))state.favorites=[];
let data,recipes,items,recipeMap,itemMap,genericIds=new Set();
let route=['craft','refine','dura','prices','cart','sources'].includes(location.hash.slice(1))?location.hash.slice(1):'craft';
let filter='all',query='',sort='featured',page=1,priceQuery='',priceMode='used',pricePage=1,selected=null,recipeHistory=[],toastTimer;
const PAGE_SIZE=24,PRICE_SIZE=40;
const categories=[['all','book','Wszystkie'],['gems','gem','Gemy'],['weapons','sword','Broń'],['armor','shield','Zbroje'],['upgrades','hammer','Ulepszenia'],['alchemy','flask','Alchemia'],['accessories','spark','Dodatki'],['pat','gear','PAT'],['favorites','star','Ulubione']];
const navs=[['craft','book','Receptury','Crafting'],['refine','hammer','Rafinacja +20','Rafinacja'],['dura','shield','Wzmocnienie DURA','DURA'],['prices','coins','Cennik i plecak','Cennik'],['cart','bag','Lista zakupów','Zakupy']];
const categoryLabels={'Gem Cutting':'Szlifowanie gemów','Armor Craft':'Tworzenie zbroi','Advanced Armor Craft':'Zaawansowane zbroje','Weapon Craft':'Tworzenie broni','Advanced Weapon Craft':'Zaawansowana broń','Alchemy Craft':'Alchemia','Advanced Alchemy Craft':'Zaawansowana alchemia','PAT Craft':'Pojazdy PAT','Armor Reinforcement':'Wzmocnienie zbroi','Advanced Armor Reinforcement':'Zaawansowane wzmocnienie zbroi','Armor Endowment':'Nasycenie zbroi','Advanced Armor Endowment':'Zaawansowane nasycenie zbroi','Weapon Hardening':'Hartowanie broni','Advanced Weapon Hardening':'Zaawansowane hartowanie','Weapon Darkening':'Przyciemnianie broni','Advanced Weapon Darkening':'Zaawansowane przyciemnianie','Weapon Balancing':'Wyważanie broni','Advanced Weapon Balancing':'Zaawansowane wyważanie','Advanced Weapon Enchanting':'Zaklinanie broni','SubItem Craft':'Przedmioty dodatkowe','Advanced SubItem Craft':'Zaawansowane dodatki','Accessory Craft':'Biżuteria','Face Item Craft':'Akcesoria twarzy'};
const chemicalNames=['Low Essence','Essence','Low Ether','Ether','High Ether','Elixir','Hime','Low Enthiric','Enthiric','Hermes'];

function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageAvailable=true;}catch{storageAvailable=false;toast('Nie udało się zapisać w przeglądarce. Wyeksportuj kopię w Cenniku.');}}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function getItem(id){return itemMap.get(String(id))||{id:String(id),name:String(id),icon:'assets/unknown.svg'};}
function itemIcon(item,cls=''){return `<span class="item-icon ${item.category==='Gem Cutting'?'gem':''} ${cls}"><img src="${esc(item.icon||'assets/unknown.svg')}" alt="" loading="lazy" width="40" height="40"></span>`;}
function getCategory(r){if(r.category==='Gem Cutting')return'gems';if(r.category==='PAT Craft')return'pat';if(/Hardening|Darkening|Balancing|Enchanting|Reinforcement|Endowment/.test(r.category))return'upgrades';if(/Armor Craft/.test(r.category))return'armor';if(/Weapon Craft/.test(r.category))return'weapons';if(/Alchemy/.test(r.category))return'alchemy';return'accessories';}
function materialKey(recipe,mat){return `${recipe.id}:${mat.id}`;}
function resolveMaterial(recipe,mat,choices=state.choices){const chosen=choices[materialKey(recipe,mat)];const source=chosen&&itemMap.has(chosen)&&!genericIds.has(chosen)?getItem(chosen):null;return source?{...mat,...source,quantity:mat.quantity,originalId:mat.id,isGeneric:false,chosen:true}:{...mat,originalId:mat.id};}
function effectiveMaterials(r,choices=state.choices){return (state.recipeEdits[r.id]?.materials||r.materials).map(m=>resolveMaterial(r,m,choices));}
function craftFee(id){return state.craftFees[id]===undefined?0:state.craftFees[id];}
function craftResult(recipe,runs=1,choices=state.choices,fee=craftFee(recipe.id)){const mats=effectiveMaterials(recipe,choices);const prices={...state.prices},inventory={...state.inventory};for(const m of mats)if(m.isGeneric){delete prices[m.id];delete inventory[m.id];}return calculateCraft({materials:mats.map(m=>({id:m.id,quantity:m.quantity})),quantity:runs,outputQuantity:1,fee,prices,inventory});}
function navCount(){return state.cart.reduce((sum,x)=>sum+(Number(x.runs)||0),0);}
function updateNavCount(){document.querySelectorAll('[data-cart-count]').forEach(el=>{el.textContent=int(navCount());el.hidden=navCount()===0;});}
function ctx(){return {state,save,esc,money,num,icon,items,itemMap,toast,navigate};}
function navigate(next){if(!['craft','refine','dura','prices','cart','sources'].includes(next))return;route=next;if(location.hash!==`#${next}`)history.replaceState(null,'',`#${next}`);if($('#recipe-dialog').open)$('#recipe-dialog').close();recipeHistory=[];renderShell();window.scrollTo({top:0,behavior:'instant'});}

function renderShell(){
const current=navs.find(n=>n[0]===route)?.[2]||'Źródła i dane';
$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a href="#craft" class="brand" data-route="craft"><img src="./assets/forge.svg" alt="" width="45" height="45"><div><div class="brand-name">ROSE Forge</div><div class="brand-caption">WARSZTAT ARTISANA</div></div></a><div class="nav-label">TWÓJ WARSZTAT</div><nav class="nav-list" aria-label="Nawigacja główna">${navs.map(n=>`<button class="nav-btn ${route===n[0]?'active':''}" data-route="${n[0]}" ${route===n[0]?'aria-current="page"':''}>${icon(n[1])}<span>${n[2]}</span>${n[0]==='cart'?`<span data-cart-count class="nav-count" ${navCount()===0?'hidden':''}>${int(navCount())}</span>`:''}</button>`).join('')}</nav><div class="nav-label" style="margin-top:26px">O PROJEKCIE</div><button class="nav-btn ${route==='sources'?'active':''}" data-route="sources">${icon('info')}<span>Źródła i aktualność</span></button><div class="side-bottom"><div class="save-indicator"><span class="dot"></span>${storageAvailable?'Zapis na tym urządzeniu':'Zapis przeglądarki niedostępny'}</div><p class="side-note">Twoje ceny, plecak i plany zostają tutaj. Kopię możesz pobrać w Cenniku.</p><p class="side-note" style="margin-top:16px">Fanowski warsztat<br>ROSE Online Global</p></div></aside><header class="topbar"><div class="mobile-brand"><img src="./assets/forge.svg" alt=""><span>ROSE Forge</span></div><div class="breadcrumb">Warsztat ${icon('chevron','width="12" height="12"')} <strong>${current}</strong></div><span class="server-chip"><span class="dot"></span>ROSE Online Global</span></header><main id="main" class="main"></main><nav class="mobile-nav" aria-label="Główne sekcje">${navs.map(n=>`<button class="${route===n[0]?'active':''}" data-route="${n[0]}" ${route===n[0]?'aria-current="page"':''}>${icon(n[1])}<span>${n[3]}</span>${n[0]==='cart'?`<span data-cart-count class="nav-count" ${navCount()===0?'hidden':''}>${int(navCount())}</span>`:''}</button>`).join('')}</nav></div>`;
const main=$('#main');
if(route==='craft')renderCraft();else if(route==='prices')renderPrices();else if(route==='cart')renderCart();else if(route==='sources')renderSources();else if(route==='refine')mountRefinery(main,ctx());else if(route==='dura')mountDurability(main,ctx());
}
function footer(){return `<footer class="footer"><span>ROSE Forge · Fanowski projekt dla ROSE Online Global</span><button data-route="sources">Źródła danych i aktualność ${icon('arrow','width="11" height="11"')}</button></footer>`;}
function renderCraft(){
const gems=['Diamond [7]','Ruby [7]','Peridot [7]'].map(name=>recipes.find(x=>x.name===name)||recipes.find(x=>x.category==='Gem Cutting'));
$('#main').innerHTML=`<section class="hero"><div class="hero-copy"><div class="eyebrow">OD PIERWSZEGO MATERIAŁU DO GOTOWEGO EKWIPUNKU</div><h1>Policz materiały.<br><em>Zaplanuj swój craft.</em></h1><p>Znajdź recepturę, policz potrzebne materiały i sprawdź koszt. Wszystko w jednym warsztacie.</p><div class="hero-badges"><span>${icon('gem')} Receptury z gry</span><span>${icon('coins')} Twoje ceny w Zulie</span><span>${icon('bag')} Wspólna lista zakupów</span></div></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div>${gems.map((g,i)=>`<div class="artifact ${i===1?'middle':i===2?'last':''}"><img src="${esc(g.icon)}" alt=""></div>`).join('')}<span class="spark a">✦</span><span class="spark b">✧</span><span class="spark c">✦</span><span class="artifact-caption">ZAPLANUJ SWÓJ NASTĘPNY UPGRADE</span></div></section><section class="stats-strip" aria-label="Warsztat w liczbach"><div class="stat"><span class="stat-icon">${icon('book')}</span><div><div class="stat-value">${int(recipes.length)}</div><div class="stat-label">receptur w katalogu</div></div></div><div class="stat"><span class="stat-icon">${icon('gem')}</span><div><div class="stat-value">200</div><div class="stat-label">receptur gemów</div></div></div><div class="stat"><span class="stat-icon">${icon('hammer')}</span><div><div class="stat-value">+20</div><div class="stat-label">plan rafinacji</div></div></div><div class="stat"><span class="stat-icon">${icon('coins')}</span><div><div class="stat-value">${int(Object.values(state.prices).filter(v=>Number.isFinite(v)).length)}</div><div class="stat-label">twoich zapisanych cen</div></div></div></section><section aria-labelledby="catalog-title"><div class="section-title"><div><h2 id="catalog-title">Księga receptur</h2><p>Wybierz przedmiot i zajrzyj do jego receptury.</p></div><button class="text-btn" data-route="prices">Ustaw ceny ${icon('arrow')}</button></div><div class="toolbar"><label class="search-wrap">${icon('search')}<input id="recipe-search" class="search" type="search" placeholder="Szukaj przedmiotu lub materiału, np. Diamond, Steel…" aria-label="Szukaj receptur" value="${esc(query)}"></label><select class="select" id="recipe-sort" aria-label="Sortuj receptury"><option value="featured" ${sort==='featured'?'selected':''}>Polecane na początek</option><option value="name" ${sort==='name'?'selected':''}>Nazwa A–Z</option><option value="level-desc" ${sort==='level-desc'?'selected':''}>Poziom: od najwyższego</option><option value="level-asc" ${sort==='level-asc'?'selected':''}>Poziom: od najniższego</option></select></div><div class="filter-row" aria-label="Kategorie receptur">${categories.map(c=>`<button class="filter ${filter===c[0]?'active':''}" data-filter="${c[0]}" aria-pressed="${filter===c[0]}">${icon(c[1])}${c[2]}</button>`).join('')}</div><div id="recipe-results"></div></section>${footer()}`;
renderRecipeGrid();
}
function filterRecipes(){let rs=recipes.filter(r=>filter==='all'||filter==='favorites'&&state.favorites.includes(r.id)||getCategory(r)===filter);const q=query.trim().toLocaleLowerCase('pl');if(q)rs=rs.filter(r=>[r.name,r.itemType,r.category,categoryLabels[r.category],r.job,...r.materials.map(m=>m.name)].join(' ').toLowerCase().includes(q));
const preferred=['Diamond [7]','Ruby [7]','Sapphire [7]','Peridot [7]','Topaz [7]','Emerald [7]','Garnet [7]','Pink Opal [7]'];
rs.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='level-desc'?(b.level||0)-(a.level||0)||a.name.localeCompare(b.name):sort==='level-asc'?(a.level||0)-(b.level||0)||a.name.localeCompare(b.name):(preferred.includes(a.name)?preferred.indexOf(a.name):-1)-(preferred.includes(b.name)?preferred.indexOf(b.name):-1));
if(sort==='featured'){rs.sort((a,b)=>{let aa=preferred.indexOf(a.name),bb=preferred.indexOf(b.name);if(aa>=0||bb>=0)return(aa<0?999:aa)-(bb<0?999:bb);return (a.category==='PAT Craft')-(b.category==='PAT Craft')||(b.level||0)-(a.level||0)||a.name.localeCompare(b.name);});}return rs;}
function renderRecipeGrid(){const rs=filterRecipes();const pages=Math.max(1,Math.ceil(rs.length/PAGE_SIZE));page=Math.min(Math.max(1,page),pages);const current=rs.slice((page-1)*PAGE_SIZE,page*PAGE_SIZE);
$('#recipe-results').innerHTML=`<div class="result-line"><span>${int(rs.length)} receptur${query?` dla „${esc(query)}”`:''} · koszty według twoich cen</span><button data-route="sources">Dane społecznościowe ${icon('info','width="12" height="12"')}</button></div>${current.length?`<div class="recipe-grid">${current.map(r=>{const result=craftResult(r);return `<article class="recipe-card"><button class="card-main" data-recipe="${esc(r.id)}" aria-label="Otwórz recepturę ${esc(r.name)}"><div class="card-top">${itemIcon(r)}<span class="level-badge">${r.category==='Gem Cutting'?'Gem':r.level?'Lv. '+r.level:'Craft'}</span></div><h3 class="card-name">${esc(r.name)}</h3><div class="card-type">${esc(categoryLabels[r.category]||r.category)}</div></button><button class="card-favorite ${state.favorites.includes(r.id)?'on':''}" data-favorite="${esc(r.id)}" aria-label="${state.favorites.includes(r.id)?'Usuń z':'Dodaj do'} ulubionych: ${esc(r.name)}" aria-pressed="${state.favorites.includes(r.id)}">${icon('star')}</button><div class="card-bottom"><span>${r.materials.length} składnik${r.materials.length===1?'':r.materials.length<5?'i':'ów'}</span><button class="card-arrow" data-recipe="${esc(r.id)}"><strong>${r.category==='PAT Craft'&&!state.patConfirmed[r.id]?'Sprawdź PAT':compact(result.marketCost)}</strong>${icon('arrow')}</button></div>${r.category==='PAT Craft'?'<div class="card-warn">Zmiana receptur · 16.10.2026</div>':''}</article>`;}).join('')}</div><div class="pagination"><button data-page="${page-1}" ${page===1?'disabled':''}>← Wstecz</button><span>${page} / ${pages}</span><button data-page="${page+1}" ${page===pages?'disabled':''}>Dalej →</button></div>`:`<div class="empty">${icon('search','width="30" height="30"')}<h3>${filter==='favorites'?'Zapisz swoje ulubione receptury':'Nie ma takiej receptury'}</h3><p>${filter==='favorites'?'Kliknij gwiazdkę przy przedmiocie, aby mieć go zawsze pod ręką.':'Spróbuj angielskiej nazwy z gry albo wyszukaj składnik.'}</p><button class="btn" data-clear-search>Pokaż wszystkie</button></div>`}`;
}

function genericControl(r,m){if(!m.isGeneric)return'';const key=materialKey(r,m);let choices=[];if(m.name==='Chemical')choices=chemicalNames.map(n=>items.find(i=>i.name===n)).filter(Boolean);const value=state.choices[key]||'';
return choices.length?`<select class="input generic-select" data-choice="${esc(key)}" aria-label="Wybierz ${esc(m.name)}"><option value="">Wybierz konkretny materiał</option>${choices.map(i=>`<option value="${esc(i.id)}" ${value===i.id?'selected':''}>${esc(i.name)}</option>`).join('')}</select>`:`<input class="input generic-select" list="material-options" data-choice-name="${esc(key)}" value="${value?esc(getItem(value).name):''}" placeholder="Materiał wskazany w grze" aria-label="Konkretny materiał z grupy ${esc(m.name)}">`;
}
function openRecipe(id,preserve=false,fromBack=false){const r=recipeMap.get(id);if(!r)return;const d=$('#recipe-dialog');if(!preserve&&!fromBack){if(d.open&&selected&&selected!==id)recipeHistory.push(selected);else if(!d.open)recipeHistory=[];}selected=id;const oldScroll=preserve?d.scrollTop:0;const runs=state.recipeRuns[id]||1;const result=craftResult(r,runs);const mats=effectiveMaterials(r);const genericMissing=mats.filter(m=>m.isGeneric);const pat=r.category==='PAT Craft';const editable=!!state.recipeEdits[r.id]?.editing;const originalMats=state.recipeEdits[r.id]?.materials||r.materials;const grouped=new Map();for(const m of originalMats){if(grouped.has(m.id))grouped.get(m.id).quantity+=m.quantity;else grouped.set(m.id,{...m});}const matSource=editable?originalMats:[...grouped.values()];
d.innerHTML=`<div class="dialog-head"><span>${recipeHistory.length?'<button class="text-btn" data-recipe-back>← Wróć do receptury</button>':'RECEPTURA · ROSE ONLINE GLOBAL'}</span><button class="icon-btn" data-close-dialog aria-label="Zamknij recepturę">${icon('close')}</button></div><div class="dialog-body"><div class="recipe-detail-head">${itemIcon(r,'lg')}<div><div class="eyebrow">${esc(categoryLabels[r.category]||r.category)}</div><h2 id="recipe-title">${esc(r.name)}</h2><p>${r.level?`Poziom używania: ${r.level} · `:''}${r.job&&r.job!=='All'?esc(r.job):'Receptura craftingu'}</p></div></div>${pat?`<div class="panel-note danger-note"><strong>PAT zmieniono 16.10.2026.</strong> To starsza receptura. Porównaj ją z grą; możesz poprawić materiały poniżej i potwierdzić je przed dodaniem do planu. <a href="https://forum.roseonlinegame.com/topic/7789-patch-notes-2026-10-16-dolphin-island-rmlui-desert-of-the-dead/" target="_blank" rel="noopener">Aktualizacja ↗</a></div>`:''}<div class="field-grid"><label class="field"><span>Liczba prób craftingu</span><input class="input" type="number" min="1" max="99999" step="1" data-recipe-runs value="${runs}"></label><label class="field"><span>Opłata Artisana / próbę (Zulie)</span><input class="input" inputmode="decimal" data-craft-fee value="${inputValue(craftFee(id))}" placeholder="0 = bez opłaty"></label></div><p class="linkline">Liczymy pełne zestawy materiałów na podaną liczbę prób. Udany craft i liczba sztuk wyniku zależą od receptury oraz gry.</p><div class="cost-grid"><div class="cost-tile"><span>Wartość materiałów + opłaty</span><strong>${pat&&!state.patConfirmed[id]?'Do sprawdzenia':money(result.marketCost)}</strong><span>${result.marketCost===null?`Znana część: ${money(result.marketKnownCost)}`:'Łącznie na '+int(runs)+' '+trialWord(runs)}</span></div><div class="cost-tile"><span>Do wydania po odjęciu plecaka</span><strong>${pat&&!state.patConfirmed[id]?'Do sprawdzenia':money(result.cashCost)}</strong><span>${result.cashCost===null?`Znana część: ${money(result.cashKnownCost)}`:'Za brakujące materiały i usługę'}</span></div></div>${genericMissing.length?`<div class="panel-note info">${icon('info','width="14" height="14"')} Receptura wskazuje grupę materiału. Wybierz konkretny składnik akceptowany w grze — jego jakość wpływa na szansę craftingu.</div>`:''}<div class="section-title" style="margin-top:22px"><h3>Potrzebne materiały</h3><button class="text-btn" data-edit-recipe>${editable?'Zakończ edycję':'Popraw z gry'} ${icon('gear')}</button></div><div class="table-wrap recipe-dialog-table"><table><thead><tr><th>Materiał</th><th class="num">${editable?'Na próbę':'Potrzeba'}</th><th class="num">W plecaku</th><th class="num">Cena / szt.</th></tr></thead><tbody>${matSource.map((base,index)=>{const m=resolveMaterial(r,base);const row=result.materials.find(x=>x.id===m.id)||{};return `<tr><td><div class="item-cell">${itemIcon(m,'small-icon')}<div><strong>${esc(m.name)}</strong>${base.isGeneric?`<div class="tiny muted">Grupa: ${esc(base.name)}</div>${genericControl(r,base)}`:''}${!base.isGeneric&&recipeMap.has(m.id)?`<div><button class="text-btn tiny" data-recipe="${esc(m.id)}">Receptura składnika ↗</button></div>`:''}${editable?`<input list="material-options" class="input generic-select" data-edit-material-name="${index}" value="${esc(base.name)}" aria-label="Nazwa materiału ${index+1}"><button class="text-btn danger" data-delete-recipe-material="${index}">Usuń składnik</button>`:''}</div></div></td><td class="num">${editable?`<input class="input mini qty" type="number" min="1" data-edit-material-qty="${index}" value="${base.quantity}" aria-label="Ilość materiału na próbę">`:`<strong data-required="${esc(m.id)}">${num(row.required)}</strong><div data-buy="${esc(m.id)}" class="tiny ${row.buy===0?'balance-ok':'muted'}">${row.buy===0?'Masz komplet':'Kup '+num(row.buy)}</div>`}</td><td class="num"><input class="input mini qty" inputmode="numeric" data-inventory="${esc(m.id)}" value="${inputValue(state.inventory[m.id]??0)}" aria-label="Posiadane: ${esc(m.name)}" ${m.isGeneric?'disabled':''}></td><td class="num"><input class="input mini price" inputmode="decimal" data-price="${esc(m.id)}" value="${inputValue(state.prices[m.id])}" placeholder="Brak ceny" aria-label="Cena ${esc(m.name)} w Zulie" ${m.isGeneric?'disabled':''}></td></tr>`;}).join('')}</tbody></table></div>${editable?`<div class="button-row"><button class="btn small" data-add-recipe-material>${icon('plus')} Dodaj składnik</button><button class="btn small ghost" data-reset-recipe>Przywróć bazową recepturę</button></div><p class="tiny muted" style="margin-top:10px">Zmiany dotyczą twojej kopii na tym urządzeniu. Nowe składniki wpisuj tak jak w grze; wybór z listy połączy je z Cennikiem.</p>`:''}${pat?`<label class="check-row" style="margin-top:16px"><input type="checkbox" data-pat-confirm ${state.patConfirmed[id]?'checked':''}>Potwierdzam skład i ilości z aktualnego okna gry.</label>`:''}<p class="tiny warn" data-missing-price-note style="margin-top:11px" ${result.unknownPriceIds?.length?'':'hidden'}>Brakuje cen ${result.unknownPriceIds?.length||0} składników. Puste pole oznacza nieznaną cenę; wpisz 0 tylko dla darmowego materiału.</p><div class="dialog-actions"><button class="btn primary" data-add-cart ${pat&&!state.patConfirmed[id]?'disabled':''}>${icon('bag')} Dodaj ${int(runs)} ${trialWord(runs)} do planu</button><button class="btn ghost" data-favorite="${esc(r.id)}">${icon('star')} ${state.favorites.includes(r.id)?'Zapisano':'Ulubione'}</button></div><details class="details-box"><summary>O tej recepturze i kosztach</summary><p>Materiały pochodzą z Lucky’s Crafting House i ROSE Online Toolbox. ${r.ingredientsVerifiedAt?'Skład tej receptury gema porównano z bazą Lucky’s 24.10.2026.':'Import bazy: 04.01.2026; aktualność konkretnej receptury sprawdź w grze.'} Poziom przy przedmiocie to wymaganie do noszenia, a nie poziom umiejętności craftingu.</p><p>Wartość materiałów uwzględnia także własne zapasy. Kwota „Do wydania” obejmuje tylko braki i wpisaną opłatę Artisana. Kwoty nie przewidują liczby udanych prób ani ewentualnego częściowego zużycia materiałów przy porażce.</p><a href="${esc(r.sourceUrl)}" target="_blank" rel="noopener">Źródło receptury ↗</a></details><datalist id="material-options">${items.map(i=>`<option value="${esc(i.name)}"></option>`).join('')}</datalist></div>`;
if(!d.open)d.showModal();d.scrollTop=oldScroll;if(!preserve)$('[data-close-dialog]',d).focus();
}

function addToCart(){const r=recipeMap.get(selected);if(!r)return;if(r.category==='PAT Craft'&&!state.patConfirmed[r.id])return;const choices={};for(const m of (state.recipeEdits[r.id]?.materials||r.materials)){const key=materialKey(r,m);if(state.choices[key])choices[key]=state.choices[key];}const snapshot=effectiveMaterials(r).map(m=>({id:m.id,name:m.name,icon:m.icon,quantity:m.quantity,isGeneric:!!m.isGeneric}));const runs=state.recipeRuns[r.id]||1;const fee=craftFee(r.id);const signature=JSON.stringify([r.id,snapshot.map(m=>[m.id,m.quantity]),fee]);const match=state.cart.find(x=>x.signature===signature);if(match)match.runs+=runs;else state.cart.push({key:'plan-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),recipeId:r.id,runs,fee,materials:snapshot,signature,addedAt:new Date().toISOString()});save();updateNavCount();toast(`Dodano do planu: ${r.name} × ${runs}`);}
function shoppingResult(){const combined=new Map();let fees=0,unknownFee=false;for(const line of state.cart){const r=recipeMap.get(line.recipeId);if(!r)continue;const mats=line.materials||effectiveMaterials(r);for(const m of mats){const prior=combined.get(m.id);const qty=m.quantity*line.runs;if(prior)prior.quantity+=qty;else combined.set(m.id,{...m,quantity:qty});}if(Number.isFinite(line.fee))fees+=line.fee*line.runs;else unknownFee=true;}const prices={...state.prices},inventory={...state.inventory};for(const m of combined.values())if(m.isGeneric){delete prices[m.id];delete inventory[m.id];}const result=calculateCraft({materials:[...combined.values()].map(m=>({id:m.id,quantity:m.quantity})),quantity:1,outputQuantity:1,fee:unknownFee?null:fees,prices,inventory});return {result,materials:combined,fees,unknownFee};}
function renderCart(){const {result,materials}=shoppingResult();$('#main').innerHTML=`<header class="page-head"><div class="eyebrow">JEDEN PLAN · WSPÓLNE MATERIAŁY</div><h1>Lista zakupów</h1><p>Składniki ze wszystkich receptur sumują się. Twój plecak odejmujemy raz od łącznego zapotrzebowania.</p></header>${state.cart.length?`<div class="cols-two"><div><section class="panel"><div class="panel-heading"><h2>Twój plan craftingu</h2><span class="status-badge">${state.cart.length} pozycji · ${int(navCount())} prób</span></div>${state.cart.map(line=>{const r=recipeMap.get(line.recipeId)||getItem(line.recipeId);return `<div class="cart-line">${itemIcon(r,'small-icon')}<div class="cart-title"><button data-recipe="${esc(r.id)}"><strong>${esc(r.name)}</strong></button><p class="tiny muted">Pełne zestawy na ${int(line.runs)} ${trialWord(line.runs)}${(line.materials||[]).some(m=>m.isGeneric)?' · wybierz materiał w recepturze i dodaj ponownie':''}</p></div><input class="input mini qty" type="number" min="1" max="99999" data-cart-runs="${esc(line.key)}" value="${line.runs}" aria-label="Liczba prób ${esc(r.name)}"><button class="icon-btn" data-remove-cart="${esc(line.key)}" aria-label="Usuń ${esc(r.name)} z planu">${icon('trash')}</button></div>`;}).join('')}<div class="button-row"><button class="btn ghost" data-route="craft">${icon('plus')} Dodaj recepturę</button><button class="btn ghost" data-clear-cart>${icon('trash')} Wyczyść plan</button></div></section><section class="panel"><div class="panel-heading"><h2>Materiały do zebrania</h2><button class="text-btn" data-export-shopping>${icon('download')} CSV</button></div><div class="table-wrap"><table><thead><tr><th>Materiał</th><th class="num">Potrzeba</th><th class="num">Masz</th><th class="num">Kup</th><th class="num">Cena / szt.</th><th class="num">Do zapłaty</th></tr></thead><tbody>${(result.materials||[]).map(row=>{const m=materials.get(row.id)||getItem(row.id);return `<tr><td><div class="item-cell">${itemIcon(m,'small-icon')}<div><strong>${esc(m.name)}</strong>${m.isGeneric?'<div class="tiny warn">Niewybrana grupa materiału</div>':''}</div></div></td><td class="num">${num(row.required)}</td><td><input class="input mini qty" inputmode="numeric" data-inventory="${esc(row.id)}" value="${inputValue(state.inventory[row.id]??0)}" aria-label="W plecaku ${esc(m.name)}" ${m.isGeneric?'disabled':''}></td><td class="num ${row.buy===0?'mint':'gold'}">${num(row.buy)}</td><td><input class="input mini price" inputmode="decimal" data-price="${esc(row.id)}" value="${inputValue(state.prices[row.id])}" placeholder="Brak ceny" aria-label="Cena ${esc(m.name)}" ${m.isGeneric?'disabled':''}></td><td class="num">${money(row.cashCost)}</td></tr>`;}).join('')}</tbody></table></div></section></div><aside class="panel calc-results"><div class="eyebrow">BUDŻET TWOJEGO PLANU</div><div class="result-hero"><div class="label">Do wydania po odjęciu plecaka</div><div class="value">${money(result.cashCost)}</div><div class="sub">${result.cashCost===null?`Znana część: ${money(result.cashKnownCost)}`:'Materiały do kupienia + opłaty Artisana'}</div></div><div class="result-row"><span>Pełna wartość planu</span><strong>${money(result.marketCost)}</strong></div><div class="result-row"><span>Opłaty Artisana</span><strong>${money(result.feeCost)}</strong></div><div class="result-row"><span>Rodzaje materiałów</span><strong>${materials.size}</strong></div><div class="result-row"><span>Składniki bez wyceny</span><strong>${result.unknownPriceIds?.length||0}</strong></div><div class="panel-note info">Zapasy w plecaku nie zmniejszają wartości przedmiotów. Zmniejszają kwotę, którą trzeba jeszcze wydać.</div><p class="tiny muted">Lista zawiera pełne zestawy na próby craftingu. Nie gwarantuje udanej produkcji. Dodane pozycje pamiętają skład z chwili dodania; po zmianie receptury dodaj ją ponownie.</p><div class="button-row"><button class="btn primary" data-export-shopping>${icon('download')} Pobierz listę CSV</button></div></aside></div>`:`<section class="empty">${icon('bag','width="40" height="40"')}<h3>Warsztat czeka na pierwszy plan</h3><p>Otwórz recepturę, ustaw liczbę prób i dodaj ją do listy.<br>Połączymy powtarzające się składniki.</p><button class="btn primary" data-route="craft">${icon('book')} Przeglądaj receptury</button></section>`}${footer()}`;}

function usedItemIds(){const ids=new Set([...Object.keys(state.prices),...Object.keys(state.inventory)]);for(const c of state.cart)for(const m of c.materials||[])ids.add(m.id);if(selected){const r=recipeMap.get(selected);if(r)for(const m of effectiveMaterials(r))ids.add(m.id);}for(const id of state.favorites){const r=recipeMap.get(id);if(r)for(const m of effectiveMaterials(r))ids.add(m.id);}return ids;}
function renderPrices(){const count=Object.values(state.prices).filter(Number.isFinite).length;const inv=Object.values(state.inventory).filter(x=>x>0).length;$('#main').innerHTML=`<header class="page-head"><div class="eyebrow">TWÓJ RYNEK · TWOJE ZAPASY</div><h1>Cennik i plecak</h1><p>Wpisz ceny widoczne w sklepach graczy. Warsztat użyje ich we wszystkich kalkulatorach. Ceny nie aktualizują się automatycznie.</p></header><section class="panel"><div class="bank-summary"><span><strong>${count}</strong> zapisanych cen</span><span><strong>${inv}</strong> rodzajów w plecaku</span><span class="save-indicator"><span class="dot"></span>Zapis w tej przeglądarce</span></div><div class="toolbar"><label class="search-wrap">${icon('search')}<input id="price-search" class="search" type="search" value="${esc(priceQuery)}" aria-label="Szukaj w cenniku" placeholder="Nazwa materiału, gema lub przedmiotu…"></label><select id="price-mode" class="select" aria-label="Filtr cennika"><option value="used" ${priceMode==='used'?'selected':''}>Używane w twoich planach</option><option value="materials" ${priceMode==='materials'?'selected':''}>Materiały i runy</option><option value="all" ${priceMode==='all'?'selected':''}>Wszystkie przedmioty</option><option value="priced" ${priceMode==='priced'?'selected':''}>Z wpisaną ceną</option></select></div><div id="price-results"></div></section><section class="panel"><h2>Kopia twojego warsztatu</h2><p class="small muted">Eksport zawiera ceny, plecak, ulubione, listę zakupów i ustawienia kalkulatorów. Wczytaj plik na drugim urządzeniu, aby przenieść plan.</p><div class="button-row"><button class="btn" data-export-backup>${icon('download')} Pobierz kopię JSON</button><label class="btn ghost" for="import-backup">${icon('upload')} Wczytaj kopię</label><input id="import-backup" type="file" accept="application/json,.json" hidden></div><p class="tiny muted" style="margin-top:12px">Import łączy twoje ceny i zapasy z plikiem; zapisane tam wartości mają pierwszeństwo. Wyczyszczenie danych przeglądarki usuwa zapis lokalny.</p></section>${footer()}`;renderPriceRows();}
function renderPriceRows(){let list=items.filter(i=>!genericIds.has(i.id));const q=priceQuery.trim().toLowerCase();if(q)list=list.filter(i=>i.name.toLowerCase().includes(q));else if(priceMode==='used'){const used=usedItemIds();list=list.filter(i=>used.has(i.id));}if(priceMode==='materials')list=list.filter(i=>i.type==='material'||i.id.startsWith('ref:')||i.id.startsWith('chemical:'));if(priceMode==='priced')list=list.filter(i=>Number.isFinite(state.prices[i.id]));list=[...list].sort((a,b)=>a.name.localeCompare(b.name));const pages=Math.max(1,Math.ceil(list.length/PRICE_SIZE));pricePage=Math.min(Math.max(1,pricePage),pages);const visible=list.slice((pricePage-1)*PRICE_SIZE,pricePage*PRICE_SIZE);
$('#price-results').innerHTML=visible.length?`<div class="result-line"><span>${int(list.length)} przedmiotów</span><span>1 z = 1 Zulie</span></div><div class="table-wrap"><table><thead><tr><th>Przedmiot</th><th class="num">Cena za sztukę (Zulie)</th><th class="num">Posiadasz (szt.)</th></tr></thead><tbody>${visible.map(i=>`<tr><td><div class="item-cell">${itemIcon(i,'small-icon')}<strong>${esc(i.name)}</strong></div></td><td class="num"><input class="input mini price" inputmode="decimal" data-price="${esc(i.id)}" value="${inputValue(state.prices[i.id])}" placeholder="Brak ceny" aria-label="Cena ${esc(i.name)} w Zulie"></td><td class="num"><input class="input mini qty" inputmode="numeric" data-inventory="${esc(i.id)}" value="${inputValue(state.inventory[i.id]??0)}" aria-label="Posiadasz ${esc(i.name)}"></td></tr>`).join('')}</tbody></table></div><div class="pagination"><button data-price-page="${pricePage-1}" ${pricePage===1?'disabled':''}>← Wstecz</button><span>${pricePage} / ${pages}</span><button data-price-page="${pricePage+1}" ${pricePage===pages?'disabled':''}>Dalej →</button></div>`:`<div class="empty"><h3>${q?'Brak takiego przedmiotu':'Jeszcze nie masz wpisów'}</h3><p>Wyszukaj materiał albo wybierz „Wszystkie przedmioty”. Możesz też wpisywać ceny bezpośrednio w recepturze.</p><button class="btn" data-all-prices>Pokaż wszystkie materiały</button></div>`;}

function renderSources(){const sources=[['Receptury i ikony','ROSE Online Toolbox + Lucky’s Crafting House','https://roseonlinetoolbox.com/crafting','2791 receptur po sprawdzeniu kompletności. Baza źródłowa: 04.01.2026. 200 receptur gemów porównano ponownie z aktualną bazą Lucky’s 24.10.2026. Pozostałe wymagają porównania z grą, szczególnie PAT.'],['Zmiany PAT i sklepów — 16.10.2026','Oficjalne informacje o aktualizacji','https://forum.roseonlinegame.com/topic/7789-patch-notes-2026-10-16-dolphin-island-rmlui-desert-of-the-dead/','PAT otrzymał nowe receptury rozwoju. Starsze wpisy mają ostrzeżenie i wymagają potwierdzenia przed dodaniem do planu. Dawnych cen materiałów w Honor/Valor Shop nie przedstawiamy jako aktualnej oferty.'],['Rafinacja do +20','Poradnik Game Mastera HoneyBuns','https://forum.roseonlinegame.com/topic/5590-guide-how-to-refine/','Mapowanie materiałów, zasada działania Venurune i Plutorune oraz rozróżnienie rafinacji od ulepszeń Artisana. Szanse, ilości i opłaty wpisujesz z aktualnego okna gry.'],['Progi spadku po porażce','Wątek społeczności — 2023','https://forum.roseonlinegame.com/topic/3925-refining-guide/','Opcjonalny preset z forum nie stanowi potwierdzonej aktualnej tabeli. Zawsze porównaj go z komunikatem w grze.'],['Wzmocnienie DURA u Saki','Poradnik Game Mastera — 03.02.2025','https://forum.roseonlinegame.com/topic/6519-guide-how-to-reinforce-to-increase-durability/','Osobny proces zwiększania durability, z materiałami Reinforcement Powder i Alloy. Kalkulator rozdziela trzy tryby ryzyka i nie zgaduje całkowitego kosztu do 100 DURA.'],['Szanse craftingu','Aktualizacja formuły — 07.03.2025','https://forum.roseonlinegame.com/topic/6637-patch-notes-2025-03-07-wandering-wanderings-speedy-summons-youve-got-mail/','CON, poziom postaci i jakość materiału wpływają na craft. Nie stosujemy starej niezweryfikowanej formuły do obiecywania sukcesu.'],['Gemy 10 i Plutorune','Oficjalna aktualizacja — 31.05.2026','https://forum.roseonlinegame.com/topic/7664-patch-notes-2026-05-31-clan-skills-treasure-chests-gem-10-difficulty-drop-rate-increase/','Trudność gemów 10 została zmieniona. Plutorune dodano do dropu Kingów na Orlo.']];$('#main').innerHTML=`<header class="page-head"><div class="eyebrow">JASNE ŹRÓDŁA · JAWNE ZAŁOŻENIA</div><h1>Co wiemy o danych?</h1><p>ROSE Forge jest fanowskim narzędziem do planowania. Każda cena pochodzi od ciebie, a przy zmianach gry pokazujemy, co wymaga sprawdzenia.</p></header><div class="cols-two"><section class="panel"><h2>Źródła warsztatu</h2>${sources.map((s,i)=>`<article class="source-card"><span class="source-number">${String(i+1).padStart(2,'0')}</span><div><h3><a href="${s[2]}" target="_blank" rel="noopener">${s[0]} ↗</a></h3><div class="tiny gold" style="margin:4px 0 8px">${s[1]}</div><p>${s[3]}</p></div></article>`).join('')}</section><aside><section class="panel"><h2>Jak czytać koszty</h2><div class="result-row"><span>Brak ceny</span><strong>Wartość nieznana</strong></div><div class="result-row"><span>Wpisane 0</span><strong>Materiał bez kosztu</strong></div><div class="result-row"><span>Wartość pełna</span><strong>Także własne materiały</strong></div><div class="result-row"><span>Do wydania</span><strong>Po odjęciu plecaka</strong></div><p class="small muted" style="margin-top:13px">Średni koszt rafinacji to wynik modelu dla wpisanych szans, a nie gwarantowany budżet. Model uwzględnia cofnięcia po porażkach i koszt odrabiania poziomów.</p></section><section class="panel"><h2>Twoje dane</h2><p class="small muted">Ceny, zapasy i plany zapisują się w tej przeglądarce. Eksport JSON pozwala przenieść je na inne urządzenie. Nie ma połączenia z kontem w grze.</p><div class="button-row"><button class="btn" data-route="prices">Kopia danych ${icon('arrow')}</button></div></section><section class="panel"><p class="tiny muted">Nazwy i grafiki przedmiotów należą do ich właścicieli. Źródła ikon: Lucky’s Crafting House / ROSE Online Toolbox. ROSE Forge nie jest oficjalnym produktem Rednim Games ani Gravity. Brakująca ikona jest oznaczona neutralnym znakiem zapytania.</p></section></aside></div>${footer()}`;}

function download(name,contents,type){const blob=new Blob([contents],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportBackup(){download('rose-forge-kopia.json',JSON.stringify({app:'rose-forge',version:1,exportedAt:new Date().toISOString(),state},null,2),'application/json');toast('Kopia warsztatu jest gotowa do pobrania.');}
function csvCell(value){return '"'+String(value??'').replace(/"/g,'""')+'"';}
function exportShopping(){const {result,materials}=shoppingResult();const rows=[['Materiał','Potrzeba','Posiadasz','Do kupienia','Cena za sztukę Zulie','Koszt zakupu Zulie']];for(const r of result.materials||[])rows.push([materials.get(r.id)?.name||r.id,r.required,r.owned,r.buy,r.unitPrice,r.cashCost]);rows.push(['Opłaty Artisana','','','','',result.feeCost]);rows.push(['SUMA DO WYDANIA','','','','',result.cashCost??'Niepełna wycena']);download('rose-forge-lista-zakupow.csv','\ufeff'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Lista zakupów jest gotowa do pobrania.');}
async function importBackup(file){if(!file)return;if(file.size>5e6){toast('Plik jest zbyt duży. Limit kopii to 5 MB.');return;}try{const input=JSON.parse(await file.text());if(input.app!=='rose-forge'||input.version!==1||!input.state||typeof input.state!=='object')throw Error('To nie jest kopia ROSE Forge.');const s=input.state;for(const m of [...Object.values(s.recipeEdits||{}).flatMap(x=>Array.isArray(x?.materials)?x.materials:[]),...(Array.isArray(s.cart)?s.cart.flatMap(x=>Array.isArray(x?.materials)?x.materials:[]):[])]){if(typeof m?.id==='string'&&m.id.startsWith('custom:')&&typeof m.name==='string'&&m.name.trim()&&!itemMap.has(m.id)){const i={id:m.id,name:m.name.slice(0,150),icon:'assets/unknown.svg',type:'material'};items.push(i);itemMap.set(i.id,i);}}for(const name of ['prices','inventory']){if(s[name]&&typeof s[name]==='object'&&!Array.isArray(s[name]))for(const [id,v]of Object.entries(s[name]))if(id!=='__proto__'&&id!=='constructor'&&id!=='prototype'&&itemMap.has(id)&&(v===null||Number.isFinite(v)&&v>=0))state[name][id]=v;}if(Array.isArray(s.favorites))state.favorites=[...new Set([...state.favorites,...s.favorites.filter(id=>recipeMap.has(id))])];if(Array.isArray(s.cart))for(const row of s.cart){if(recipeMap.has(row.recipeId)&&Number.isInteger(row.runs)&&row.runs>0&&row.runs<=99999&&typeof row.key==='string'&&!state.cart.some(x=>x.key===row.key)){const materials=Array.isArray(row.materials)?row.materials.filter(m=>typeof m.id==='string'&&Number.isFinite(m.quantity)&&m.quantity>0).map(m=>({...getItem(m.id),id:m.id,name:String(m.name||getItem(m.id).name),quantity:m.quantity,isGeneric:!!m.isGeneric})):[];if(materials.length)state.cart.push({...row,materials,fee:Number.isFinite(row.fee)&&row.fee>=0?row.fee:null});}}for(const name of ['choices','craftFees','recipeRuns','patConfirmed','recipeEdits','refine','dura'])if(s[name]&&typeof s[name]==='object'&&!Array.isArray(s[name])){const safe=JSON.parse(JSON.stringify(s[name]),(k,v)=>['__proto__','constructor','prototype'].includes(k)?undefined:v);state[name]={...state[name],...safe};}save();renderPrices();toast('Kopia wczytana. Połączono ceny, zapasy i plany.');}catch(e){toast('Nie udało się wczytać kopii: '+e.message);}}
function afterDataChange(){save();if($('#recipe-dialog').open&&selected)openRecipe(selected,true);if(route==='cart')renderCart();}
function editRecipe(){const r=recipeMap.get(selected);if(!r)return;if(!state.recipeEdits[r.id])state.recipeEdits[r.id]={materials:r.materials.map(m=>({...m})),editing:true};else state.recipeEdits[r.id].editing=!state.recipeEdits[r.id].editing;save();openRecipe(selected,true);}
function nameToItem(name){return items.find(i=>i.name.toLowerCase()===String(name).trim().toLowerCase());}
function customItem(name){const id='custom:'+name.trim().toLowerCase();if(!itemMap.has(id)){const i={id,name:name.trim(),icon:'assets/unknown.svg',type:'material'};items.push(i);itemMap.set(id,i);}return getItem(id);}

document.addEventListener('click',e=>{const el=e.target.closest('button,a,label');if(!el)return;if(el.dataset.route){e.preventDefault();navigate(el.dataset.route);return;}if(el.hasAttribute('data-close-dialog')){$('#recipe-dialog').close();return;}if(el.hasAttribute('data-recipe-back')){const prev=recipeHistory.pop();if(prev)openRecipe(prev,false,true);return;}if(el.hasAttribute('data-delete-recipe-material')){const index=Number(el.dataset.deleteRecipeMaterial);if(state.recipeEdits[selected].materials.length<2){toast('Receptura musi mieć co najmniej jeden składnik.');return;}state.recipeEdits[selected].materials.splice(index,1);delete state.patConfirmed[selected];save();openRecipe(selected,true);return;}if(el.dataset.recipe){openRecipe(el.dataset.recipe);return;}if(el.dataset.filter){filter=el.dataset.filter;page=1;renderCraft();return;}if(el.dataset.page){page=Number(el.dataset.page);renderRecipeGrid();$('#catalog-title').scrollIntoView({block:'start',behavior:'smooth'});return;}if(el.dataset.pricePage){pricePage=Number(el.dataset.pricePage);renderPriceRows();return;}if(el.hasAttribute('data-clear-search')){query='';filter='all';page=1;renderCraft();return;}if(el.dataset.favorite){const id=el.dataset.favorite;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();if(route==='craft')renderRecipeGrid();if($('#recipe-dialog').open)openRecipe(selected,true);return;}if(el.hasAttribute('data-add-cart')){addToCart();return;}if(el.dataset.removeCart){state.cart=state.cart.filter(x=>x.key!==el.dataset.removeCart);save();renderCart();updateNavCount();return;}if(el.hasAttribute('data-clear-cart')){state.cart=[];save();renderCart();updateNavCount();toast('Plan wyczyszczony. Ceny i plecak pozostają zapisane.');return;}if(el.hasAttribute('data-export-backup')){exportBackup();return;}if(el.hasAttribute('data-export-shopping')){exportShopping();return;}if(el.hasAttribute('data-all-prices')){priceMode='materials';priceQuery='';pricePage=1;renderPrices();return;}if(el.hasAttribute('data-edit-recipe')){editRecipe();return;}if(el.hasAttribute('data-add-recipe-material')){state.recipeEdits[selected].materials.push({id:'custom:nowy-material-'+Date.now(),name:'Nowy materiał',icon:'assets/unknown.svg',quantity:1,isGeneric:false});save();openRecipe(selected,true);return;}if(el.hasAttribute('data-reset-recipe')){delete state.recipeEdits[selected];delete state.patConfirmed[selected];save();openRecipe(selected,true);return;}});
let searchTimer;
function refreshLiveRecipe(){
  const dialog=$('#recipe-dialog');if(!dialog.open||!selected)return;
  const r=recipeMap.get(selected);const runs=state.recipeRuns[selected]||1;const result=craftResult(r,runs);
  const tiles=dialog.querySelectorAll('.cost-tile');const patBlocked=r.category==='PAT Craft'&&!state.patConfirmed[r.id];
  if(tiles[0]){tiles[0].querySelector('strong').textContent=patBlocked?'Do sprawdzenia':money(result.marketCost);tiles[0].querySelectorAll('span')[1].textContent=result.marketCost===null?`Znana część: ${money(result.marketKnownCost)}`:`Łącznie na ${int(runs)} ${trialWord(runs)}`;}
  if(tiles[1]){tiles[1].querySelector('strong').textContent=patBlocked?'Do sprawdzenia':money(result.cashCost);tiles[1].querySelectorAll('span')[1].textContent=result.cashCost===null?`Znana część: ${money(result.cashKnownCost)}`:'Za brakujące materiały i usługę';}
  for(const row of result.materials||[]){for(const el of dialog.querySelectorAll('[data-required]'))if(el.dataset.required===row.id)el.textContent=num(row.required);for(const el of dialog.querySelectorAll('[data-buy]'))if(el.dataset.buy===row.id){el.textContent=row.buy===0?'Masz komplet':'Kup '+num(row.buy);el.className='tiny '+(row.buy===0?'balance-ok':'muted');}}
  const note=dialog.querySelector('[data-missing-price-note]');if(note){note.hidden=!result.unknownPriceIds?.length;note.textContent=`Brakuje cen ${result.unknownPriceIds?.length||0} składników. Puste pole oznacza nieznaną cenę; wpisz 0 tylko dla darmowego materiału.`;}
  if(dialog.querySelector('input:invalid'))for(const tile of tiles)tile.querySelector('strong').textContent='Sprawdź pola';const button=dialog.querySelector('[data-add-cart]');if(button){button.innerHTML=icon('bag')+` Dodaj ${int(runs)} ${trialWord(runs)} do planu`;button.disabled=patBlocked||!!dialog.querySelector('input:invalid');}
}
function refreshLiveCart(){
  if(route!=='cart')return;const {result}=shoppingResult();const panel=$('#main .calc-results');if(!panel)return;
  panel.querySelector('.value').textContent=$('#main input:invalid')?'Sprawdź pola':money(result.cashCost);panel.querySelector('.sub').textContent=result.cashCost===null?`Znana część: ${money(result.cashKnownCost)}`:'Materiały do kupienia + opłaty Artisana';
  const values=panel.querySelectorAll('.result-row strong');if(values[0])values[0].textContent=money(result.marketCost);if(values[1])values[1].textContent=money(result.feeCost);if(values[3])values[3].textContent=result.unknownPriceIds?.length||0;
  for(const row of result.materials||[]){const input=[...document.querySelectorAll('#main [data-price]')].find(el=>el.dataset.price===row.id);const tr=input?.closest('tr');if(tr){const cells=tr.querySelectorAll('td');cells[1].textContent=num(row.required);cells[3].textContent=num(row.buy);cells[5].textContent=money(row.cashCost);}}
}
document.addEventListener('input',event=>{
  const t=event.target;let touched=false;let invalid='';
  if(t.dataset.price){const v=parseNumber(t.value);invalid=t.value.trim()&&(v===null||v<0||v>1e15)?'Wpisz poprawną, nieujemną cenę.':'';state.prices[t.dataset.price]=invalid?null:v;touched=true;}
  else if(t.dataset.inventory){const v=parseNumber(t.value);invalid=t.value.trim()&&(v===null||v<0||!Number.isInteger(v)||v>1e9)?'Wpisz nieujemną liczbę całkowitą.':'';if(!invalid)state.inventory[t.dataset.inventory]=v??0;touched=true;}
  else if(t.hasAttribute('data-recipe-runs')){const v=Number(t.value);invalid=!Number.isInteger(v)||v<1||v>99999?'Podaj od 1 do 99 999 prób.':'';if(!invalid)state.recipeRuns[selected]=v;touched=true;}
  else if(t.hasAttribute('data-craft-fee')){const v=parseNumber(t.value);invalid=v===null||v<0||v>1e15?'Podaj opłatę co najmniej 0 Zulie.':'';state.craftFees[selected]=invalid?null:v;touched=true;}
  else if(t.dataset.cartRuns){const v=Number(t.value);invalid=!Number.isInteger(v)||v<1||v>99999?'Podaj od 1 do 99 999 prób.':'';const row=state.cart.find(x=>x.key===t.dataset.cartRuns);if(row&&!invalid)row.runs=v;touched=true;}
  if(touched){t.setCustomValidity(invalid);save();refreshLiveRecipe();refreshLiveCart();updateNavCount();}
});
document.addEventListener('input',e=>{if(e.target.id==='recipe-search'){query=e.target.value;page=1;clearTimeout(searchTimer);searchTimer=setTimeout(renderRecipeGrid,100);}if(e.target.id==='price-search'){priceQuery=e.target.value;pricePage=1;clearTimeout(searchTimer);searchTimer=setTimeout(renderPriceRows,100);}});
document.addEventListener('change',e=>{const t=e.target;if(t.closest('[data-refinery-root]'))return;if(t.id==='recipe-sort'){sort=t.value;page=1;renderRecipeGrid();return;}if(t.id==='price-mode'){priceMode=t.value;pricePage=1;renderPriceRows();return;}if(t.id==='import-backup'){importBackup(t.files[0]);return;}if(t.dataset.price){const val=parseNumber(t.value);if(t.value.trim()&&val===null||val!==null&&(val<0||val>1e15)){toast('Wpisz cenę od 0 do 1 000 000 000 000 000.');t.value=inputValue(state.prices[t.dataset.price]);return;}state.prices[t.dataset.price]=val;afterDataChange();return;}if(t.dataset.inventory){const val=parseNumber(t.value);if(val!==null&&(val<0||!Number.isInteger(val)||val>1e9)||t.value.trim()&&val===null){toast('Wpisz nieujemną, całkowitą liczbę sztuk.');t.value=state.inventory[t.dataset.inventory]??0;return;}state.inventory[t.dataset.inventory]=val??0;afterDataChange();return;}if(t.hasAttribute('data-recipe-runs')){const val=Number(t.value);if(!Number.isInteger(val)||val<1||val>99999){toast('Liczba prób musi wynosić od 1 do 99 999.');t.value=state.recipeRuns[selected]||1;return;}state.recipeRuns[selected]=val;afterDataChange();return;}if(t.hasAttribute('data-craft-fee')){const val=parseNumber(t.value);if(val===null||val<0||val>1e15){toast('Podaj opłatę co najmniej 0 Zulie.');return;}state.craftFees[selected]=val;afterDataChange();return;}if(t.dataset.choice){if(t.value)state.choices[t.dataset.choice]=t.value;else delete state.choices[t.dataset.choice];afterDataChange();return;}if(t.dataset.choiceName){const i=nameToItem(t.value);if(!i||genericIds.has(i.id)){toast('Wybierz konkretny materiał z listy, nie nazwę grupy.');return;}state.choices[t.dataset.choiceName]=i.id;afterDataChange();return;}if(t.hasAttribute('data-pat-confirm')){state.patConfirmed[selected]=t.checked;afterDataChange();return;}if(t.dataset.cartRuns){const val=Number(t.value);if(!Number.isInteger(val)||val<1||val>99999){toast('Liczba prób musi wynosić od 1 do 99 999.');return;}const c=state.cart.find(x=>x.key===t.dataset.cartRuns);if(c)c.runs=val;save();renderCart();updateNavCount();return;}if(t.hasAttribute('data-edit-material-qty')){const v=Number(t.value);if(!Number.isInteger(v)||v<1||v>99999){toast('Podaj ilość od 1 do 99 999.');return;}state.recipeEdits[selected].materials[Number(t.dataset.editMaterialQty)].quantity=v;delete state.patConfirmed[selected];afterDataChange();return;}if(t.hasAttribute('data-edit-material-name')){if(!t.value.trim()){toast('Nazwa materiału nie może być pusta.');return;}const i=nameToItem(t.value)||customItem(t.value);const m=state.recipeEdits[selected].materials[Number(t.dataset.editMaterialName)];Object.assign(m,{id:i.id,name:i.name,icon:i.icon,isGeneric:false});delete state.patConfirmed[selected];afterDataChange();return;}});
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&!e.target.src.endsWith('/assets/unknown.svg')){e.target.src='./assets/unknown.svg';e.target.alt='Brak ikony w bazie';}},true);
$('#recipe-dialog').addEventListener('click',e=>{if(e.target===$('#recipe-dialog')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right)e.target.close();}});
window.addEventListener('hashchange',()=>{const r=location.hash.slice(1);if(r!==route)navigate(r);});

async function boot(){try{const response=await fetch('./data/recipes.json');if(!response.ok)throw Error('Nie można pobrać bazy receptur.');data=await response.json();recipes=data.recipes;genericIds=new Set(recipes.flatMap(r=>r.materials.filter(m=>m.isGeneric).map(m=>m.id)));recipeMap=new Map(recipes.map(r=>[r.id,r]));items=[...data.items];itemMap=new Map(items.map(i=>[i.id,i]));for(const i of REFINERY_ITEMS||[]){const match=items.some(x=>x.name.toLowerCase()===i.name.toLowerCase())||i.genericGradeName&&items.some(x=>x.name.toLowerCase()===i.name.toLowerCase().replace(/(bindrune|talisman|apotrope) \(grade (\d)\)/,(_,kind,n)=>n+({1:'st',2:'nd',3:'rd'}[n]||'th')+' grade '+kind));if(!match&&!itemMap.has(i.id)){items.push(i);itemMap.set(i.id,i);}}for(const m of Object.values(state.recipeEdits).flatMap(x=>x.materials||[]))if(m.id?.startsWith('custom:')&&!itemMap.has(m.id)){const i={id:m.id,name:m.name,icon:m.icon||'assets/unknown.svg',type:'material'};items.push(i);itemMap.set(i.id,i);}renderShell();}catch(e){$('#app').innerHTML=`<div class="fatal"><h1>Warsztat nie mógł się otworzyć</h1><p class="muted" style="margin:15px 0">${esc(e.message)}</p><button class="btn primary" onclick="location.reload()">Spróbuj ponownie</button></div>`;}}
boot();
